class EventEmitter {
  constructor() {
    this.events = {};
  }
  subscribe(event, cb) {
    if (!this.events[event]) this.events[event] = [];
    this.events[event].push(cb);
    return { unsubscribe: () => this.events[event] = this.events[event].filter(fn => fn !== cb) };
  }
  emit(event, ...args) {
    if (this.events[event]) this.events[event].forEach(cb => cb(...args));
  }
}
