  attempt++;
  if (attempt < 3) throw new Error('Network error');
  return 'Success';
}, 3).then(res => console.log(res, 'Attempt:', attempt));

class HttpClient {
  constructor() {
    this.requestInterceptors = [];
    this.responseInterceptors = [];
  }
  useRequest(fn) { this.requestInterceptors.push(fn); }
  useResponse(fn) { this.responseInterceptors.push(fn); }
  async request(config) {
    let conf = config;
    for (let fn of this.requestInterceptors) conf = await fn(conf);
    let res = { status: 200, data: 'OK for ' + conf.url };
    for (let fn of this.responseInterceptors) res = await fn(res);
    return res;
  }
}
