function getVirtualBounds(scrollTop, containerHeight, itemHeight, totalItems, buffer = 2) {
  let startIndex = Math.max(0, Math.floor(scrollTop / itemHeight) - buffer);
  let endIndex = Math.min(totalItems - 1, Math.ceil((scrollTop + containerHeight) / itemHeight) + buffer);
  return [startIndex, endIndex];
}
