class BoundedBuffer:
    def __init__(self, capacity):
        self.cap = capacity
        self.buffer = []

    def produce(self, item):
        if len(self.buffer) < self.cap:
            self.buffer.append(item)
            return True
        return False  # Buffer full

    def consume(self):
        if len(self.buffer) > 0:
            return self.buffer.pop(0)
        return None  # Buffer empty

