def round_robin(processes, quantum):
    # processes = [(pid, burst_time)]
    rem_time = {p[0]: p[1] for p in processes}
    wt = {p[0]: 0 for p in processes}
    t = 0
    while True:
        done = True
        for pid, burst in processes:
            if rem_time[pid] > 0:
                done = False
                if rem_time[pid] > quantum:
                    t += quantum
                    rem_time[pid] -= quantum
                else:
                    t += rem_time[pid]
                    wt[pid] = t - burst
                    rem_time[pid] = 0
        if done: break
    return sum(wt.values()) / len(processes)

print('Avg Waiting Time:', round_robin([('P1', 10), ('P2', 5), ('P3', 8)], 2))

def lru_page_faults(pages, capacity):
    memory = []
    faults = 0
    for p in pages:
        if p not in memory:
            if len(memory) == capacity:
                memory.pop(0)  # Evict least recently used
            faults += 1
            memory.append(p)
        else:
            memory.remove(p)
            memory.append(p)  # Move to most recent
    return faults

print('Page Faults:', lru_page_faults([7, 0, 1, 2, 0, 3, 0, 4, 2, 3], 3))

def first_fit(blocks, processes):
    alloc = [-1] * len(processes)
    b_copy = list(blocks)
    for i, p in enumerate(processes):
        for j, b in enumerate(b_copy):
            if b >= p:
                alloc[i] = j
                b_copy[j] -= p
                break
    return alloc

