def singleNumber(nums):
    xor = 0
    for n in nums: xor ^= n
    diff = xor & (-xor)  # Rightmost set bit
    a, b = 0, 0
    for n in nums:
        if n & diff: a ^= n
        else: b ^= n
    return sorted([a, b])

