def mark_and_sweep(roots, heap_objects, references):
    visited = set()
    def dfs(node):
        if node in visited: return
        visited.add(node)
        for child in references.get(node, []):
            dfs(child)
    for root in roots: dfs(root)
    garbage = [obj for obj in heap_objects if obj not in visited]
    return garbage

print('Garbage collected:', mark_and_sweep(['R1'], ['O1', 'O2', 'O3', 'O4'], {'R1': ['O1'], 'O1': ['O2']}))

class LFUCache:
    def __init__(self, cap):
        self.cap = cap
        self.vals = {}
        self.counts = {}
    def get(self, key):
        if key not in self.vals: return -1
        self.counts[key] += 1
        return self.vals[key]
    def put(self, key, val):
        if self.cap == 0: return
        if key in self.vals:
            self.vals[key] = val
            self.counts[key] += 1
        else:
            if len(self.vals) >= self.cap:
                lfu_key = min(self.counts, key=lambda k: self.counts[k])
                del self.vals[lfu_key]; del self.counts[lfu_key]
            self.vals[key] = val; self.counts[key] = 1

